import{_ as a,o as e,c as l,a2 as r}from"./chunks/framework.E8pQZ6KS.js";const _=JSON.parse('{"title":"操作系统安全","description":"","frontmatter":{},"headers":[],"relativePath":"安全方向/操作系统安全.md","filePath":"安全方向/操作系统安全.md","lastUpdated":1792430298000}'),i={name:"安全方向/操作系统安全.md"};function d(o,t,h,n,s,u){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="操作系统安全" tabindex="-1">操作系统安全 <a class="header-anchor" href="#操作系统安全" aria-label="Permalink to &quot;操作系统安全&quot;">​</a></h1><blockquote><p>校内核心课「操作系统及安全」（第 4 学期）。操作系统是所有安全机制的宿主，理解系统安全 = 理解攻击的落点。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>提权、持久化、沙箱逃逸等高级攻击都发生在 OS 层面；</li><li>安全运维、应急响应要懂系统加固（账号、权限、服务、日志）；</li><li>校内课程直接考核系统安全机制，是专业核心能力之一。</li></ul><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li><a href="./../专业基础/操作系统.html">操作系统</a>：进程、内存、文件系统、内核态/用户态</li></ul><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><ul><li>身份认证与访问控制（DAC、MAC、最小权限）</li><li>Linux 权限体系：文件权限、SUID/SGID、sudo 策略、Capabilities 概念</li><li>安全机制：ASLR、NX、Canary、PIE（与 <a href="./二进制安全与逆向.html">二进制安全与逆向</a> 呼应）</li><li>内核安全概念：系统调用、内核模块、提权原理</li><li>系统加固：账号策略、服务最小化、日志审计、基线检查</li><li>Windows 安全基础：注册表、服务、域控概念（拓展）</li></ul><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>《操作系统安全》（教材，以校内指定为准）</td><td>教材</td><td>课程主线</td></tr><tr><td>CSAPP 第 8 章（异常控制流）</td><td>书</td><td>用户态/内核态转换的基础</td></tr><tr><td>pwn.college（<a href="https://pwn.college/" target="_blank" rel="noreferrer">pwn.college</a>）</td><td>在线课程</td><td>含系统安全相关模块</td></tr><tr><td><a href="https://www.cisecurity.org/" target="_blank" rel="noreferrer">Linux 安全加固基线（CIS Benchmarks）</a></td><td>文档</td><td>业界基线标准</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li>在 Linux 虚拟机里把权限体系「玩明白」：建用户、改权限、做 SUID 实验；</li><li>尝试复现一次经典提权（如利用 SUID 程序或内核漏洞——仅在自建靶机）；</li><li>结合 <a href="./网络攻防.html">网络攻防</a>：攻防演练中「横向移动 + 提权」是核心链条。</li></ul><h2 id="校内对应" tabindex="-1">校内对应 <a class="header-anchor" href="#校内对应" aria-label="Permalink to &quot;校内对应&quot;">​</a></h2><ul><li>操作系统及安全（第 4 学期，核心课，含课程设计）</li><li>可信计算（方向课，拓展）</li></ul>',14)])])}const b=a(i,[["render",d]]);export{_ as __pageData,b as default};
